const issues = Array.isArray($json) ? $json : ($json.data ?? []);
return issues.filter(issue => !issue.pull_request).map(issue => ({ json: { issue_number: issue.number, title: issue.title, body: issue.body ?? '', prompt: `You are the specification editor in a human-controlled software factory. Rewrite this rough GitHub issue using these exact headings: Goal, Why, Scope, Constraints, Acceptance criteria, Open questions. Do not invent requirements. You advise; a human alone approves. Return Markdown only.

Title: ${issue.title}
Body: ${issue.body ?? ''}` } }));
